import { Section } from "./ui.tsx";

type Props = { deal: Deal; intel: DealIntelligence };

export function OverviewTab({ deal, intel }: Props) {
  const scores = effectiveScores(intel);
  const changes = intel.scoreChanges.filter((c) => c.key === "investmentConviction").slice(-3);
  const waiting = intel.tasks.filter((t) => t.status === "waiting" || t.status === "open");

  return (
    <div>
      <Section
        title="Investment case"
        lead={`${intel.profile.company} is in ${intel.stage.replace("_", " ")}. ${convictionCopy()}`}
      >
        <div className="grid gap-5 sm:grid-cols-4 lg:grid-cols-8">
          {PIPELINE_SCORE_KEYS.map((key) => (
            <ScoreChip key={key} scoreKey={key} value={scores[key]} />
          ))}
        </div>
        {intel.thesis.exceptions.length ? (
          <p className="mt-5 font-mono text-[12px] text-flag-amber">
            Thesis exception — continue evaluating. This is not a rejection.
          </p>
        ) : null}
        {intel.triage ? (
          <p className="mt-4 text-[15px] text-paper/80">
            Triage recommendation: <strong>{recommendationLabel(intel.triage.outcome)}</strong>.{" "}
            {intel.triage.note}
          </p>
        ) : null}
      </Section>

      <Section title="Next best action" lead={intel.nextAction.reason}>
        <p className="font-serif text-3xl">{intel.nextAction.title}</p>
        <p className="mt-3 font-mono text-[12px] text-paper/50">
          Impact {intel.nextAction.decisionImpact} · information {intel.nextAction.informationValue} ·
          cost {intel.nextAction.cost} · {intel.nextAction.time} · {intel.nextAction.urgency.replace("_", " ")}
        </p>
      </Section>

      <Section title="Waiting on">
        {waiting.length === 0 ? (
          <p className="text-paper/60">Nothing outstanding.</p>
        ) : (
          <ul className="space-y-3">
            {waiting.map((task) => (
              <li key={task.id}>
                <p className="text-[16px]">{task.title}</p>
                <p className="font-mono text-[12px] text-paper/50">
                  {task.owner}
                  {task.waitingOn ? ` · waiting on ${task.waitingOn}` : ""}
                  {task.deadline ? ` · ${task.deadline}` : ""}
                </p>
              </li>
            ))}
          </ul>
        )}
      </Section>

      <Section title="What changed my mind" lead="Last three conviction moves.">
        {changes.length === 0 ? (
          <p className="text-paper/60">No conviction history yet — HarborMail is still a profile.</p>
        ) : (
          <ul className="space-y-3">
            {changes.map((change) => (
              <li key={change.id} className="flex flex-wrap items-baseline justify-between gap-3">
                <p>
                  {change.previous ?? "—"} → {change.next ?? "—"} · {change.reason}
                </p>
                <p className="font-mono text-[12px] text-paper/45">{when(change.date)}</p>
              </li>
            ))}
          </ul>
        )}
      </Section>

      <Section
        title="Conviction formula"
        lead={`0.28·opportunity + 0.12·thesis + 0.18·(100−risk) + 0.12·(100−uncertainty) + 0.12·evidence + 0.12·valuation + 0.06·portfolio. Weights: ${JSON.stringify(CONVICTION_WEIGHTS)}.`}
      >
        <p className="text-[15px] text-paper/70">{intel.scoreBreakdown?.convictionNote}</p>
        <OverrideForm dealId={deal.id} />
      </Section>
    </div>
  );
}

function OverrideForm({ dealId }: { dealId: string }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [key, setKey] = useState<ScoreKey>("investmentConviction");
  const [value, setValue] = useState("70");
  const [reason, setReason] = useState("");
  const [error, setError] = useState<string | null>(null);

  return (
    <form
      className="mt-6 grid gap-3 md:grid-cols-[10rem_6rem_1fr_auto]"
      onSubmit={(event) => {
        event.preventDefault();
        setError(null);
        start(async () => {
          const res = await fetch(`/api/deals/${dealId}/override`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ key, value: Number(value), reason }),
          });
          if (!res.ok) {
            setError("Override needs a score, a number, and a reason.");
            return;
          }
          setReason("");
          router.refresh();
        });
      }}
    >
      <select
        value={key}
        onChange={(e) => setKey(e.target.value as ScoreKey)}
        className="border border-white/15 bg-desk px-2 py-2 text-[13px]"
      >
        {PIPELINE_SCORE_KEYS.map((item) => (
          <option key={item} value={item}>
            {SCORE_LABELS[item]}
          </option>
        ))}
        <option value="portfolioFit">{scoreKeyLabel("portfolioFit")}</option>
      </select>
      <input
        type="number"
        min={0}
        max={100}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        className="border-b border-white/20 bg-transparent px-2 py-2"
      />
      <input
        required
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        placeholder="Reason for the override — stored on the deal"
        className="border-b border-white/20 bg-transparent px-2 py-2 text-[14px]"
      />
      <button
        type="submit"
        disabled={pending}
        className="bg-paper px-3 py-2 text-[13px] text-ink disabled:opacity-50"
      >
        {pending ? "Saving…" : "Override"}
      </button>
      {error ? <p className="text-[13px] text-flag-red md:col-span-4">{error}</p> : null}
    </form>
  );
}

