            {conviction.slice(1).map((c) => {
              const delta =
                c.previous != null && c.next != null ? c.next - c.previous : null;
              return (
                <li key={c.id}>
                  {c.reason}
                  {delta != null ? `: ${delta > 0 ? "+" : ""}${delta}` : ""}
                </li>
              );
            })}
          </ul>
        </Section>
      ) : null}
      <Section title="Deal timeline">
        {intel.timeline.length === 0 ? (
