"use client";

import Link from "next/link";
import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { DealSummary } from "@/lib/diligence/types";
import { DEAL_STAGES, STAGE_LABELS, type DealStage } from "@/lib/intelligence/types";
import { scoreTone } from "@/lib/intelligence/scores";
import { scoreDisplay } from "@/lib/format";

type Props = {
  deals: DealSummary[];
};

export function PipelineBoard({ deals }: Props) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [stage, setStage] = useState<DealStage | "all">("all");
  const [error, setError] = useState<string | null>(null);

  const rows = useMemo(() => {
    const filtered = deals.filter((deal) => (stage === "all" ? true : deal.stage === stage));
    return [...filtered].sort((a, b) => {
      const ai = DEAL_STAGES.indexOf(a.stage as DealStage);
      const bi = DEAL_STAGES.indexOf(b.stage as DealStage);
      return (ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi);
    });
  }, [deals, stage]);

  function reseeds() {
    setError(null);
    startTransition(async () => {
      const res = await fetch("/api/deals/seed", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ force: true }),
      });
      if (!res.ok) {
        setError("Could not reload the sample deals.");
        return;
      }
      router.refresh();
    });
  }

  return (
    <section aria-labelledby="pipeline-heading">
      <div className="mb-2 flex flex-wrap items-center justify-between gap-3">
        <h2 id="pipeline-heading" className="sr-only">
          Deals
        </h2>
        <label className="text-[14px] text-mute">
          Stage
          <select
            value={stage}
            onChange={(event) => setStage(event.target.value as DealStage | "all")}
            className="ml-2 border border-line bg-desk px-2 py-1 text-[14px] text-paper"
          >
            <option value="all">All</option>
            {DEAL_STAGES.map((item) => (
              <option key={item} value={item}>
                {STAGE_LABELS[item]}
              </option>
            ))}
          </select>
        </label>
        <button
          type="button"
          onClick={reseeds}
          disabled={pending}
          className="text-[14px] text-mute hover:text-paper disabled:opacity-50"
        >
          {pending ? "Reloading…" : "Reset samples"}
        </button>
      </div>

      <div>
        {rows.map((deal) => (
          <Link key={deal.id} href={`/deals/${deal.id}`} className="deal-row-card">
            <div>
              <h3 className="font-serif text-[28px] leading-none">{deal.company || deal.name}</h3>
              {deal.thesisException ? (
                <p className="mt-2 text-[13px] font-medium text-flag-amber">Thesis exception</p>
              ) : null}
            </div>
            <p className="text-[14px] text-copper">{deal.stage ? STAGE_LABELS[deal.stage] : "—"}</p>
            <div className="text-[15px]">
              <p>
                <span className={scoreTone("investmentConviction", deal.investmentConviction)}>
                  {scoreDisplay(deal.investmentConviction)}
                </span>
                <span className="text-mute"> conviction</span>
                <span className="mx-2 text-mute">·</span>
                <span className={scoreTone("risk", deal.riskScore)}>{scoreDisplay(deal.riskScore)}</span>
                <span className="text-mute"> risk</span>
              </p>
              <p className="mt-2 text-mute">{deal.nextAction ?? "No next action yet"}</p>
            </div>
          </Link>
        ))}
      </div>
      {error ? <p className="mt-3 text-[14px] text-flag-red">{error}</p> : null}
    </section>
  );
}

"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import type { Deal } from "@/lib/diligence/types";
import type { DealIntelligence } from "@/lib/intelligence/types";
import { STAGE_LABELS } from "@/lib/intelligence/types";
import { AppChrome } from "../AppChrome";
import { StageRail } from "../pipeline/StageRail";
import { ICTab } from "./ICTab";
import { NumbersTab } from "./NumbersTab";
import { OverviewTab } from "./OverviewTab";
import { ThesisTab } from "./ThesisTab";

const TABS = [
  { id: "overview", label: "Overview" },
  { id: "thesis", label: "Thesis" },
  { id: "numbers", label: "Numbers" },
  { id: "decision", label: "Decision" },
] as const;

const ALIASES: Record<string, (typeof TABS)[number]["id"]> = {
  ic: "decision",
  timeline: "decision",
  valuation: "decision",
  questions: "numbers",
  claims: "numbers",
  evidence: "numbers",
  findings: "numbers",
  risks: "overview",
  people: "overview",
  world: "thesis",
  stage: "overview",
  process: "overview",
  documents: "overview",
};

type TabId = (typeof TABS)[number]["id"];

type Props = {
  deal: Deal;
  intel: DealIntelligence;
};

export function DealShell({ deal, intel }: Props) {
  const params = useSearchParams();
  const router = useRouter();
  const raw = params.get("tab") ?? "overview";
  const tab = (TABS.some((t) => t.id === raw) ? raw : ALIASES[raw] ?? "overview") as TabId;

  function open(id: TabId) {
    router.replace(`/deals/${deal.id}?tab=${id}`, { scroll: false });
  }

  return (
    <div className="min-h-screen">
      <a href="#deal-main" className="skip-link">
        Skip to deal
      </a>
      <header className="mx-auto max-w-4xl px-6 pb-6 pt-8 md:px-8">
        <AppChrome
          extra={
            <Link href={`/deals/${deal.id}/room`} className="text-[15px] text-mute hover:text-paper">
              Data room
            </Link>
          }
        />
        <div className="mt-8 flex flex-wrap items-end justify-between gap-4">
          <div>
            <h1 className="font-serif text-4xl font-medium tracking-tight">{intel.profile.company}</h1>
            <p className="mt-2 max-w-xl text-[16px] leading-7 text-mute">
              {intel.profile.product}
            </p>
          </div>
          <div className="text-right">
            <p className="text-[14px] text-copper">{STAGE_LABELS[intel.stage]}</p>
            {intel.thesis.exceptions.length ? (
              <p className="mt-1 text-[13px] font-medium text-flag-amber">Thesis exception</p>
            ) : null}
          </div>
        </div>
        <div className="mt-6">
          <StageRail current={intel.stage} />
        </div>
      </header>

      <nav className="deal-tabs mx-auto max-w-4xl px-4 md:px-6" aria-label="Deal sections">
        {TABS.map((item) => (
          <button
            key={item.id}
            type="button"
            className={`deal-tab ${tab === item.id ? "is-on" : ""}`}
            onClick={() => open(item.id)}
          >
            {item.label}
          </button>
        ))}
      </nav>

      <main id="deal-main" className="mx-auto max-w-4xl px-6 pb-20 md:px-8">
        {tab === "overview" ? <OverviewTab deal={deal} intel={intel} /> : null}
        {tab === "thesis" ? <ThesisTab intel={intel} /> : null}
        {tab === "numbers" ? <NumbersTab deal={deal} intel={intel} /> : null}
        {tab === "decision" ? <ICTab intel={intel} /> : null}
      </main>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useTransition } from "react";
import type { Deal } from "@/lib/diligence/types";
import { convictionCopy, effectiveScores } from "@/lib/intelligence/scores";
import type { DealIntelligence, ScoreKey } from "@/lib/intelligence/types";
import { recommendationLabel, scoreDisplay } from "@/lib/format";
import { scoreTone } from "@/lib/intelligence/scores";
import { Note, Section } from "./ui";

const DEMO_SCORES: ScoreKey[] = ["investmentConviction", "opportunityQuality", "risk", "thesisFit"];
const LABELS: Record<ScoreKey, string> = {
  investmentConviction: "Conviction",
  opportunityQuality: "Opportunity",
  risk: "Risk",
  thesisFit: "Thesis",
  uncertainty: "Uncertainty",
  evidenceConfidence: "Evidence",
  valuationAttractiveness: "Valuation",
  portfolioFit: "Portfolio",
};

type Props = { deal: Deal; intel: DealIntelligence };

export function OverviewTab({ deal, intel }: Props) {
  const scores = effectiveScores(intel);
  const waiting = intel.tasks.filter((t) => t.status !== "done").slice(0, 3);
  const people = intel.people[0];

  return (
    <div>
      <Section title="The case" lead={convictionCopy()}>
        <div className="grid grid-cols-2 gap-x-8 gap-y-6 sm:grid-cols-4">
          {DEMO_SCORES.map((key) => (
            <div key={key}>
              <p className="text-[13px] text-mute">{LABELS[key]}</p>
              <p className={`mt-1 font-serif text-4xl ${scoreTone(key, scores[key])}`}>
                {scoreDisplay(scores[key])}
              </p>
            </div>
          ))}
        </div>
        {intel.thesis.exceptions.length ? (
          <p className="mt-6 font-medium text-flag-amber">
            Thesis exception — still evaluating. This is not a rejection.
          </p>
        ) : null}
        {intel.triage ? (
          <p className="mt-4 text-[16px] leading-7">
            {recommendationLabel(intel.triage.outcome)}. {intel.triage.note}
          </p>
        ) : null}
      </Section>

      <Section title="Do next">
        <p className="font-serif text-3xl leading-tight">{intel.nextAction.title}</p>
        <Note>{intel.nextAction.reason}</Note>
      </Section>

      {waiting.length ? (
        <Section title="Waiting on">
          <ul className="space-y-3">
            {waiting.map((task) => (
              <li key={task.id}>
                <p>{task.title}</p>
                <p className="text-[14px] text-mute">
                  {task.waitingOn ?? task.owner}
                </p>
              </li>
            ))}
          </ul>
        </Section>
      ) : null}

      {people ? (
        <Section title="People">
          <p className="text-[16px] leading-7">{people.claim}</p>
          <p className="mt-2 text-mute">{people.assessment}</p>
        </Section>
      ) : null}

      {deal.id === "northstar-robotics" ? <FounderReply intel={intel} dealId={deal.id} /> : null}
    </div>
  );
}

function FounderReply({ dealId, intel }: { dealId: string; intel: DealIntelligence }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  if (intel.founderReplyApplied) {
    return (
      <Section title="Founder reply">
        <p className="text-ledger">ARR restated. Conviction updated. Next: cohort workbook.</p>
      </Section>
    );
  }
  return (
    <Section title="Founder reply" lead="Northstar sent a restated ARR definition.">
      <button
        type="button"
        disabled={pending}
        className="bg-paper px-4 py-3 text-[15px] text-ink disabled:opacity-50"
        onClick={() =>
          start(async () => {
            await fetch(`/api/deals/${dealId}/founder-reply`, { method: "POST" });
            router.refresh();
          })
        }
      >
        {pending ? "Applying…" : "Apply the ARR reply"}
      </button>
    </Section>
  );
}

import type { DealIntelligence } from "@/lib/intelligence/types";
import { Note, Section } from "./ui";

export function ThesisTab({ intel }: { intel: DealIntelligence }) {
  const t = intel.thesis;
  return (
    <div>
      <Section title="Thesis fit" lead="A miss is a warning. It never auto-rejects.">
        <p className="font-serif text-5xl">{t.score ?? "—"}</p>
        <div className="mt-4">
          <Note>{t.whyItMayStillMatter}</Note>
        </div>
      </Section>

      {t.exceptions.length ? (
        <Section title="Exception">
          {t.exceptions.map((item) => (
            <div key={item.label}>
              <p className="font-medium text-flag-amber">{item.label}</p>
              <p className="mt-2 text-[16px] leading-7 text-mute">{item.detail}</p>
            </div>
          ))}
        </Section>
      ) : null}

      <Section title="What fits">
        {t.matches.length ? (
          <ul className="space-y-2 text-[16px] leading-7">
            {t.matches.map((item) => (
              <li key={item.label}>{item.detail}</li>
            ))}
          </ul>
        ) : (
          <Note>Scoring starts after triage.</Note>
        )}
      </Section>

      {t.mismatches.length ? (
        <Section title="What does not">
          <ul className="space-y-2 text-[16px] leading-7 text-mute">
            {t.mismatches.map((item) => (
              <li key={item.label}>{item.detail}</li>
            ))}
          </ul>
        </Section>
      ) : null}
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useTransition } from "react";
import type { Deal } from "@/lib/diligence/types";
import type { DealIntelligence } from "@/lib/intelligence/types";
import { Note, Section } from "./ui";

type Props = { deal: Deal; intel: DealIntelligence };

export function NumbersTab({ deal, intel }: Props) {
  const rows = intel.claims.filter((c) => c.managementValue || c.recomputedValue);
  const flags = deal.flags;
  const question = intel.questions[0];

  return (
    <div>
      <Section
        title="Stated vs room"
        lead="Management number, then what the files actually say."
      >
        {rows.length === 0 && flags.length === 0 ? (
          <Note>No numbers yet. HarborMail is still just a profile.</Note>
        ) : (
          <table className="pipe-table">
            <thead>
              <tr>
                <th>Claim</th>
                <th>They said</th>
                <th>We get</th>
                <th>Call</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((claim) => (
                <tr key={claim.id}>
                  <td>{claim.metric ?? claim.text}</td>
                  <td>{claim.managementValue ?? "—"}</td>
                  <td>{claim.recomputedValue ?? "—"}</td>
                  <td className="text-mute">{claim.assessment ?? claim.kind}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Section>

      {flags.length ? (
        <Section title="Flags">
          <ul className="space-y-4">
            {flags.map((flag) => (
              <li key={flag.id}>
                <p>{flag.comment}</p>
              </li>
            ))}
          </ul>
        </Section>
      ) : null}

      {question ? (
        <Section title="Open question">
          <p className="text-[17px] leading-7">{question.question}</p>
          {deal.id === "northstar-robotics" ? <FounderReply dealId={deal.id} applied={Boolean(intel.founderReplyApplied)} /> : null}
        </Section>
      ) : null}
    </div>
  );
}

function FounderReply({ dealId, applied }: { dealId: string; applied: boolean }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  if (applied) return <p className="mt-4 text-ledger">Reply applied. Conviction moved.</p>;
  return (
    <button
      type="button"
      disabled={pending}
      className="mt-5 bg-paper px-4 py-3 text-[15px] text-ink disabled:opacity-50"
      onClick={() =>
        start(async () => {
          await fetch(`/api/deals/${dealId}/founder-reply`, { method: "POST" });
          router.refresh();
        })
      }
    >
      {pending ? "Applying…" : "Apply founder ARR reply"}
    </button>
  );
}

import { recommendationLabel, scoreDisplay } from "@/lib/format";
import type { DealIntelligence } from "@/lib/intelligence/types";
import { Note, Section } from "./ui";

export function ICTab({ intel }: { intel: DealIntelligence }) {
  const ic = intel.ic;
  const walk = intel.scoreChanges.filter((c) => c.key === "investmentConviction");

  if (!ic) {
    return (
      <div>
        <Section title="Decision">
          <Note>
            {intel.stage === "source" || intel.stage === "triage"
              ? "Too early for a packet."
              : "No IC packet on this deal. Open Helio Freight for the full example."}
          </Note>
        </Section>
        {walk.length ? <ConvictionWalk walk={walk} /> : null}
      </div>
    );
  }

  return (
    <div>
      <Section title="Recommendation">
        <p className="font-serif text-4xl leading-tight">{recommendationLabel(ic.recommendation)}</p>
        <div className="mt-3">
          <Note>{ic.executiveSummary}</Note>
        </div>
      </Section>

      <Section title="Bull / bear">
        <p className="text-[16px] leading-7">
          <span className="text-ledger">Bull. </span>
          {ic.bullCase}
        </p>
        <p className="mt-4 text-[16px] leading-7">
          <span className="text-flag-amber">Bear. </span>
          {ic.bearCase}
        </p>
      </Section>

      {intel.returns ? (
        <Section title="Returns" lead={intel.returns.caveat}>
          <p>
            Base {intel.returns.scenarios.find((s) => s.name === "base")?.moic ?? "—"}x · bear{" "}
            {intel.returns.scenarios.find((s) => s.name === "bear")?.moic ?? "—"}x · bull{" "}
            {intel.returns.scenarios.find((s) => s.name === "bull")?.moic ?? "—"}x
          </p>
        </Section>
      ) : null}

      {intel.valuation ? (
        <Section title="Price">
          <p>{intel.valuation.entryValuation}</p>
          <p className="mt-2 text-mute">{intel.valuation.companyQualityVsPrice}</p>
        </Section>
      ) : null}

      <ConvictionWalk walk={walk} />
    </div>
  );
}

function ConvictionWalk({
  walk,
}: {
  walk: DealIntelligence["scoreChanges"];
}) {
  if (!walk.length) return null;
  const last = walk[walk.length - 1];
  return (
    <Section title="What changed my mind">
      <p className="font-serif text-4xl">{scoreDisplay(last.next)}</p>
      <ul className="mt-5 space-y-3">
        {walk.map((change) => {
          const delta =
            change.previous != null && change.next != null ? change.next - change.previous : null;
          return (
            <li key={change.id} className="text-[16px] leading-7">
              {change.reason}
              {delta != null && delta !== 0 ? (
                <span className={delta > 0 ? "text-ledger" : "text-flag-red"}>
                  {" "}
                  {delta > 0 ? `+${delta}` : delta}
                </span>
              ) : null}
            </li>
          );
        })}
      </ul>
    </Section>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import type { ThesisSettings } from "@/lib/intelligence/types";

type Props = { thesis: ThesisSettings };

function lines(value: string) {
  return value
    .split("\n")
    .map((item) => item.trim())
    .filter(Boolean);
}

function Field({
  label,
  hint,
  value,
  onChange,
}: {
  label: string;
  hint?: string;
  value: string;
  onChange: (value: string) => void;
}) {
  return (
    <label className="block">
      <span className="text-[14px] text-mute">{label}</span>
      {hint ? <span className="mt-1 block text-[13px] text-mute">{hint}</span> : null}
      <textarea
        value={value}
        onChange={(e) => onChange(e.target.value)}
        rows={3}
        className="mt-2 w-full border border-line bg-transparent px-3 py-2 text-[16px] leading-6"
      />
    </label>
  );
}

export function ThesisForm({ thesis }: Props) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [preferredSectors, setPreferredSectors] = useState(thesis.preferredSectors.join("\n"));
  const [avoidedSectors, setAvoidedSectors] = useState(thesis.avoidedSectors.join("\n"));
  const [preferredStages, setPreferredStages] = useState(thesis.preferredStages.join("\n"));
  const [preferredGeographies, setPreferredGeographies] = useState(thesis.preferredGeographies.join("\n"));
  const [check, setCheck] = useState(`${thesis.checkSizeMin} – ${thesis.checkSizeMax}`);
  const [hardConstraints, setHardConstraints] = useState(thesis.hardConstraints.join("\n"));

  return (
    <form
      className="grid gap-6"
      onSubmit={(event) => {
        event.preventDefault();
        setError(null);
        const [min, max] = check.split("–").map((part) => part.trim());
        const next: ThesisSettings = {
          ...thesis,
          preferredSectors: lines(preferredSectors),
          avoidedSectors: lines(avoidedSectors),
          preferredStages: lines(preferredStages),
          preferredGeographies: lines(preferredGeographies),
          checkSizeMin: min || thesis.checkSizeMin,
          checkSizeMax: max || thesis.checkSizeMax,
          hardConstraints: lines(hardConstraints),
        };
        start(async () => {
          const res = await fetch("/api/thesis", {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(next),
          });
          if (!res.ok) {
            setError("Could not save the thesis.");
            return;
          }
          router.refresh();
        });
      }}
    >
      <p className="text-[15px] leading-7 text-mute">
        Hard constraints warn. They do not auto-pass a deal. Lumen Health is the exception story.
      </p>
      <Field label="We like" value={preferredSectors} onChange={setPreferredSectors} />
      <Field
        label="We avoid"
        hint="Raises a thesis exception — the deal still gets scored."
        value={avoidedSectors}
        onChange={setAvoidedSectors}
      />
      <Field label="Stages" value={preferredStages} onChange={setPreferredStages} />
      <Field label="Geographies" value={preferredGeographies} onChange={setPreferredGeographies} />
      <label className="block">
        <span className="text-[14px] text-mute">Check size</span>
        <input
          value={check}
          onChange={(e) => setCheck(e.target.value)}
          className="mt-2 w-full border-b border-line bg-transparent py-2 text-[16px]"
        />
      </label>
      <Field label="Hard constraints" value={hardConstraints} onChange={setHardConstraints} />
      <button
        type="submit"
        disabled={pending}
        className="w-fit bg-paper px-5 py-3 text-[15px] text-ink disabled:opacity-50"
      >
        {pending ? "Saving…" : "Save thesis"}
      </button>
      {error ? <p className="text-flag-red">{error}</p> : null}
    </form>
  );
}

