import { DEAL_STAGES, type DealStage } from "@/lib/intelligence/types";

const SHORT: Record<DealStage, string> = {
  source: "Source",
  triage: "Triage",
  process: "Process",
  numbers: "Numbers",
  world: "World",
  people_product: "People",
  founder_loop: "Loop",
  ic: "IC",
  close_pass: "Close",
};

type Props = {
  current: DealStage;
};

export function StageRail({ current }: Props) {
  const here = DEAL_STAGES.indexOf(current);
  return (
    <ol className="stage-rail" aria-label="Deal stage">
      {DEAL_STAGES.map((stage, index) => {
        const state = index < here ? "done" : index === here ? "now" : "next";
        return (
          <li key={stage} className={`stage-rail-item is-${state}`}>
            <span>{SHORT[stage]}</span>
          </li>
        );
      })}
    </ol>
  );
}

