  min-width: 0;
}

.score-strip .score-label {
  font-size: 0.8125rem;
  line-height: 1.2;
  color: var(--mute);
}

.score-strip .score-value {
  margin-top: 0.4rem;
  font-family: var(--font-news), serif;
  font-size: 2rem;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.pipe-list {
  display: grid;
}

.pipe-head,
.pipe-row {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) 6.25rem 6.5rem minmax(0, 1.3fr);
  column-gap: 1.25rem;
  align-items: center;
}

.pipe-head {
  padding: 0 0 0.7rem;
  border-bottom: 1px solid var(--line);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  color: var(--mute);
}

.pipe-row {
  min-height: 4.75rem;
  padding: 1rem 0;
  border-bottom: 1px solid var(--line);
  color: inherit;
  text-decoration: none;
}

.pipe-row:hover .pipe-name {
  color: var(--copper);
}

.pipe-name {
  font-family: var(--font-news), serif;
  font-size: 1.35rem;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.pipe-name .pipe-flag {
  display: block;
  margin-top: 0.3rem;
  font-family: var(--font-plex), sans-serif;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0;
  color: var(--amber);
}

.pipe-stage {
  font-size: 0.875rem;
  color: var(--copper);
}

.pipe-score {
  font-variant-numeric: tabular-nums;
  font-size: 0.9375rem;
}

.pipe-next {
  font-size: 0.875rem;
  line-height: 1.35;
  color: var(--mute);
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 2.25rem;
  margin-bottom: 1rem;
}

.toolbar label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: var(--mute);
}

.toolbar select {
  border: 1px solid var(--line);
  background: var(--desk);
  color: var(--paper);
  padding: 0.25rem 0.5rem;
  font-size: 0.875rem;
}

@media (max-width: 640px) {
  .pipe-head {
    display: none;
  }

  .pipe-row {
    grid-template-columns: 1fr 1fr;
    row-gap: 0.35rem;
    align-items: start;
  }

  .pipe-name {
    grid-column: 1 / -1;
  }

  .pipe-next {
    grid-column: 1 / -1;
  }

  .score-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

